def max_profit_brute(prices, day, holding, cooldown):
    if day == len(prices):
        return 0
    best = max_profit_brute(prices, day + 1, holding, False)      # do nothing today
    if holding:
        best = max(best, prices[day] + max_profit_brute(prices, day + 1, False, True))    # sell today
    elif not cooldown:
        best = max(best, -prices[day] + max_profit_brute(prices, day + 1, True, False))    # buy today
    return best

