def max_profit(prices):
    hold, sold, rest = float('-inf'), 0, 0
    for price in prices:
        prev_sold = sold
        sold = hold + price                                    # sell today, using YESTERDAY's hold
        hold = max(hold, rest - price)                           # keep holding, or buy using YESTERDAY's rest
        rest = max(rest, prev_sold)                                # stay resting, or cooldown just ended
    return max(sold, rest)

