public class Main {
    static int maxProfit(int[] prices) {
        int hold = Integer.MIN_VALUE, sold = 0, rest = 0;
        for (int price : prices) {
            int prevSold = sold;
            sold = hold + price;                                      // sell today, using YESTERDAY's hold
            hold = Math.max(hold, rest - price);                        // keep holding, or buy using YESTERDAY's rest
            rest = Math.max(rest, prevSold);                              // stay resting, or cooldown just ended
        }
        return Math.max(sold, rest);
    }
}

